fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    assert_eq!(condition.len(), x.len(), "Input vectors must have the same length");
    assert_eq!(x.len(), y.len(), "Input vectors must have the same length");

    condition
        .into_iter()
        .zip(x)
        .zip(y)
        .map(|((cond, xv), yv)| if cond { xv } else { yv })
        .collect()
}

